}
.clock-hand-hr {
  transform-origin: 160px 160px;
  will-change: transform;
}
.clock-hand-min {
  transform-origin: 160px 160px;
  will-change: transform;
}

/* 时钟差速旋转与指针旋转 */
.spin-outer-cw {
  animation: spin-cw 90s infinite linear;
}
.spin-inner-ccw {
  animation: spin-ccw 120s infinite linear;
}
.clock-hand-hr {
  animation: spin-cw 40s infinite linear;
}
.clock-hand-min {
  animation: spin-cw 12s infinite linear;
